const today = new Date();
const cutoff = new Date(today.getTime() - 48 * 60 * 60 * 1000);
const dateStr = today.toLocaleDateString('en-US', {
  timeZone: 'America/Los_Angeles',
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const inciwebItems = [];
for (const item of $input.all()) {
  const d = item.json;
  if (d.pubDate) {
    const pub = new Date(d.pubDate);
    if (pub >= cutoff) {
      const title = (d.title || '').toLowerCase();
      const content = (d.content || d.summary || d['content:encoded'] || '');
      const isPNW = title.includes('oregon') || title.includes('washington') ||
                    title.includes('idaho') || title.includes(' or ') ||
                    title.includes(' wa ') || content.toLowerCase().includes('pacific northwest');
      if (isPNW) {
        inciwebItems.push({
          title: d.title || 'Unnamed Incident',
          link: d.link || '',
          pubDate: d.pubDate,
          summary: (content || '').substring(0, 500)
        });
      }
    }
  }
}

const seen = new Set();
const uniqueInciweb = inciwebItems.filter(i => {
  if (seen.has(i.title)) return false;
  seen.add(i.title);
  return true;
});

return [{
  json: {
    date: dateStr,
    inciwebItems: uniqueInciweb,
    inciwebCount: uniqueInciweb.length,
    sources: [
      'InciWeb (inciweb.nwcg.gov)',
      'NW Coordination Center (gacc.nifc.gov/nwcc)',
      'Oregon State Fire Marshal (oregon.gov/osp/sfm)',
      'Washington DNR (dnr.wa.gov)',
      'NOAA / National Weather Service (weather.gov)'
    ]
  }
}];

const date = $('Filter & Structure Data').first().json.date;
const aiContent = $input.first().json.message.content;

const sourceLinks = [
  '<a href="https://inciweb.nwcg.gov" target="_blank" rel="noopener">InciWeb — National Interagency Fire Center</a>',
  '<a href="https://gacc.nifc.gov/nwcc/" target="_blank" rel="noopener">Northwest Coordination Center (NWCC)</a>',
  '<a href="https://www.oregon.gov/osp/programs/sfm" target="_blank" rel="noopener">Oregon State Fire Marshal</a>',
  '<a href="https://www.dnr.wa.gov/programs-and-services/wildfire" target="_blank" rel="noopener">Washington DNR Wildfire</a>',
  '<a href="https://www.weather.gov/fire" target="_blank" rel="noopener">NOAA / National Weather Service — Fire Weather</a>'
];

const footer = `
<hr>
<p><strong>Sources:</strong></p>
<ul>${sourceLinks.map(l => `<li>${l}</li>`).join('')}</ul>
<p><em>This post was generated automatically from public RSS feeds and official agency websites. It is not a substitute for official emergency communications. Always follow directions from your local emergency management office.</em></p>
`;

const today = new Date();
const titleDate = today.toLocaleDateString('en-US', {
  timeZone: 'America/Los_Angeles',
  month: 'long', day: 'numeric', year: 'numeric'
});
const title = `Pacific Northwest Fire Report: Oregon and Washington Wildfire Updates for ${titleDate}`;

return [{ json: { title, content: aiContent + footer, date } }];

